// src/systems/performance.ts
function startPerformanceSystem(onTick) {
  let elapsed = 0;
  engine.addSystem((dt) => {
    elapsed += dt * 1e3;
    if (elapsed < TARGET_UPDATE_MS)
      return;
    elapsed = 0;
    onTick();
  });
}

