// src/arena/gameLoop.ts
function createGameState() {
  return {
    phase: "playing",
    sunScore: 428,
    moonScore: 381,
    seconds: 42,
    localPower: 0,
    dirty: true
  };
}
function formatClock(seconds) {
  const mm = Math.max(0, Math.floor(seconds / 60));
  const ss = Math.max(0, seconds % 60);
  return `${String(mm).padStart(2, "0")}:${String(ss).padStart(2, "0")}`;
}
function paintHud(scoreLabel, timerLabel, state) {
  setLabelText(scoreLabel, `SUN ${state.sunScore}   MOON ${state.moonScore}`);
  setLabelText(timerLabel, `${state.phase.toUpperCase()}  ${formatClock(state.seconds)}`);
  state.dirty = false;
}
function startGameLoop(rope2, scoreLabel, timerLabel, state) {
  let elapsedMs = 0;
  paintHud(scoreLabel, timerLabel, state);
  startPerformanceSystem(() => {
    elapsedMs += TARGET_UPDATE_MS;
    if (elapsedMs < 1e3 && !state.dirty)
      return;
    if (elapsedMs >= 1e3) {
      elapsedMs = 0;
      if (state.phase === "countdown") {
        state.seconds -= 1;
        if (state.seconds <= 0) {
          state.phase = "playing";
          state.seconds = 42;
        }
        state.dirty = true;
      } else if (state.phase === "playing") {
        state.seconds -= 1;
        const drift = (state.sunScore - state.moonScore) / 40;
        updateRope(Math.max(-4, Math.min(4, drift + state.localPower)));
        if (state.seconds <= 0) {
          state.phase = "finished";
          updateRope(0.15);
        }
        state.dirty = true;
      }
    }
    if (state.dirty)
      paintHud(scoreLabel, timerLabel, state);
  });
}
function pull(state, team) {
  if (state.phase !== "playing")
    return;
  state.localPower += 1;
  if (team === "sun")
    state.sunScore += 1;
  else
    state.moonScore += 1;
  state.dirty = true;
}
function rematch(state, rope2) {
  state.phase = "countdown";
  state.seconds = 3;
  state.localPower = 0;
  state.dirty = true;
  updateRope(0);
}

