// src/world.ts
function assembleWorld() {
  const dataset = createMockWorldDataset();
  const chain = createWorldBlockchainState();
  const state = createGameState();
  state.sunScore = dataset.leaderboard.sunScore;
  state.moonScore = dataset.leaderboard.moonScore;
  createSpawnPlaza();
  createCrewBases();
  createArena();
  createArenaStage();
  const rope2 = createRope();
  bindArenaControls(state, rope2);
  createPullPad();
  createJoinPad();
  createRematchPad();
  spawnPlayerAvatars(dataset.players);
  createSocialBoards();
  createGovernancePlaza();
  createAchievementTerminal();
  createPortals((id) => {
    console.log("[world] portal", id);
  });
  createWorldTutorial(true);
  const scoreLabel = worldLabel(
    `SUN ${dataset.leaderboard.sunScore}   MOON ${dataset.leaderboard.moonScore}`,
    Vector33.create(16, 2.6, 21.6),
    1.05
  );
  const timerLabel = worldLabel(`PLAYING  ${dataset.leaderboard.timeLabel}`, Vector33.create(16, 2.15, 21.6), 0.95);
  worldLabel(
    chain.demoMode ? "BLOCKCHAIN OPTIONAL  DEMO MODE" : "WALLET CONNECTED",
    Vector33.create(27.4, 3.1, 24.4),
    0.65
  );
  startGameLoop(rope2, scoreLabel, timerLabel, state);
  const graphics = resolveGraphics(DEFAULT_GRAPHICS, false);
  createAtmosphere(graphics.ambient);
  createDebugControls(() => resetRope());
  startWorldScheduler((fn) => {
    engine.addSystem(fn);
  });
  schedule("temporary", 250, () => {
    removeExpiredEntities();
    fadeTemporary();
  });
}

